<script setup lang="ts">
import { onMounted, ref } from 'vue'
import Button from 'primevue/button'
import Column from 'primevue/column'
import DataTable from 'primevue/datatable'
import InputText from 'primevue/inputtext'
import Message from 'primevue/message'
import Select from 'primevue/select'
import Tag from 'primevue/tag'
import CostStateReportChart from '~/components/charts/CostStateReportChart.vue'
import PageHeader from '~/components/design-system/PageHeader.vue'
import type { CostOverviewReport, ReportFilters, ReportingContract } from '~/types/reporting'
definePageMeta({ middleware: 'auth' })
const api = useReporting(); const report = ref<CostOverviewReport | null>(null); const contract = ref<ReportingContract | null>(null); const loading = ref(false); const error = ref<string | null>(null)
const filters = ref<ReportFilters>({}); const stateOptions = [{ label: 'All states', value: undefined }, { label: 'Field estimate', value: 'field_estimate' }, { label: 'Commitment', value: 'commitment' }, { label: 'Accrual', value: 'accrual' }, { label: 'Actual', value: 'actual' }, { label: 'Forecast', value: 'forecast' }]
async function load() { loading.value = true; error.value = null; try { const [overview, reportingContract] = await Promise.all([api.overview(filters.value), api.contract()]); report.value = overview; contract.value = reportingContract } catch (caught: unknown) { error.value = caught instanceof Error ? caught.message : 'Report failed' } finally { loading.value = false } }
async function download() { const blob = await api.export(filters.value); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'cost-overview.xlsx'; link.click(); URL.revokeObjectURL(url) }
onMounted(() => void load())
</script>
<template><div class="reports-page"><PageHeader title="Cost-state reporting" description="Shared-dimension reporting across AFE, field estimate, commitment, accrual, actual, and forecast records with source drill-through."><template #actions><Tag value="Metric policy pending" severity="warn" /><Button label="Export Excel" icon="pi pi-file-excel" outlined @click="download" /></template></PageHeader><Message severity="warn" :closable="false">Financial totals, variance, and forecast at completion remain null under <strong>pending-shared-cost-reporting</strong>.</Message><Message v-if="error" severity="error">{{ error }}</Message><section class="report-filters bulk-grid-panel"><label>Project<InputText v-model="filters.project_code" fluid /></label><label>Well<InputText v-model="filters.well_code" fluid /></label><label>AFE<InputText v-model="filters.afe_number" fluid /></label><label>Cost state<Select v-model="filters.cost_state" :options="stateOptions" option-label="label" option-value="value" show-clear fluid /></label><label>Currency<InputText v-model="filters.currency_code" fluid /></label><Button label="Apply filters" icon="pi pi-filter" :loading="loading" @click="load" /></section><section class="report-state-cards"><article v-for="state in report?.state_summaries ?? []" :key="state.cost_state"><span>{{ state.cost_state.replace('_', ' ') }}</span><strong>{{ state.amount ?? 'Pending' }}</strong><small>{{ state.transaction_count }} source records</small></article></section><section class="calculation-panel"><CostStateReportChart :states="report?.state_summaries ?? []" /><details v-if="report?.pending_metrics.length" class="pending-rules"><summary>Pending reporting metrics ({{ report.pending_metrics.length }})</summary><ul><li v-for="item in report.pending_metrics" :key="item">{{ item }}</li></ul></details></section><section v-if="contract" class="report-contract-panel"><div><span class="eyebrow">Power BI / external contract</span><h2>Reporting schema v{{ contract.contract_version }}</h2><p>{{ contract.views.length }} versioned views · direct grants {{ contract.direct_grants_status }} · transactional schema private</p></div><Tag :value="contract.contract_status" severity="info" /><div class="report-view-list"><code v-for="view in contract.views" :key="view.name">reporting.{{ view.name }}</code></div></section><section class="cost-control-history"><h2>Source drill-through</h2><DataTable :value="report?.drill_through ?? []" show-gridlines paginator :rows="25" class="bulk-grid-panel"><Column field="transaction_date" header="Date" /><Column field="project_code" header="Project" /><Column field="well_code" header="Well" /><Column field="afe_number" header="AFE" /><Column field="cost_state" header="State" /><Column field="cost_code" header="Cost code" /><Column field="vendor_code" header="Vendor" /><Column field="currency_code" header="Currency" /><Column field="amount" header="Source amount" /><Column field="source_document_reference" header="Source document" /><template #empty>No posted cost-state records match the filters.</template></DataTable></section></div></template>
